(* [comment removed for export] *)
Lemma lazy_interior_aligned : forall (a n : word),
  bv_unsigned a mod page_size = 0 -> bv_unsigned n mod page_size = 0 ->
  0 < bv_unsigned n -> bv_unsigned a + bv_unsigned n <= 2 ^ 64 ->
  lazy_interior a n = [(a, n)].
